struct ParsedSelectBranch;
struct ParsedSelectStatement;
SqlQueryResult execute_parsed_select(SqlDatabase* db, const ParsedSelectStatement& stmt);
SqlQueryResult execute_parsed_select_single(SqlDatabase* db, const ParsedSelectBranch& branch);

// Runs a nested SELECT with `outer` as the scope its unresolved columns are
// looked up in. Defined below, once SqlDatabase's own members exist; declared
// here because expression evaluation is what reaches for it.
struct NestedResult {
  bool ok = false;
  std::string error;
  std::vector<Val> first_column;  // the subquery's first column, row by row
  size_t row_count = 0;
};
// Runs a nested SELECT with `outer` pushed as the scope its own columns fall
// back to. Only the first column is handed back: that is all any of the three
// subquery forms looks at -- a scalar reads its first row, IN tests membership
// of it, EXISTS only counts.
inline NestedResult run_nested_parsed_select(SqlDatabase* db,
                                             const ParsedSelectStatement& stmt,
                                             const EvalCtx& outer) {
  NestedResult out;
  if (!db) {
    out.error = "no database for subquery";
    return out;
  }
  SqlQueryResult r;
  {
    OuterScope scope(&outer);
    r = execute_parsed_select(db, stmt);
  }
  if (!r.success) {
    out.error = r.error_message.empty() ? std::string("subquery failed") : r.error_message;
    return out;
  }
  out.ok = true;
  out.row_count = r.rows.size();
  if (!r.columns.empty()) {
    out.first_column.reserve(r.rows.size());
    // A string column stays strings: supplierid IN (SELECT supplierno ...)
    // compares text with text, so '123' does not meet '0123'.
    const bool text_col = !r.column_types.empty() && r.column_types[0] == SqlDataType::Text;
    for (SqlRow& row : r.rows) {
      if (row.values.empty() || sql_is_null(row.values[0])) out.first_column.push_back(val_null());
      else out.first_column.push_back(text_col ? val_text(row.values[0]) : val_cell(std::move(row.values[0])));
    }
  }
  return out;
}

