    tm_buf.tm_mon = (int)p.month - 1;
    tm_buf.tm_mday = (int)p.day;
    tm_buf.tm_hour = p.hour;
    tm_buf.tm_min = p.minute;
    tm_buf.tm_sec = p.second;
    tm_buf.tm_isdst = -1;
