    if (!u.empty() && u.back() == 'S') u.pop_back();
    if (u == "YEAR") return val_num(p.year);
    if (u == "MONTH") return val_num(p.month);
    if (u == "DAY") return val_num(p.day);
    if (u == "HOUR") return val_num(p.hour);
    if (u == "MINUTE") return val_num(p.minute);
    if (u == "SECOND") return val_num(p.second);
    if (u == "QUARTER") return val_num((p.month - 1) / 3 + 1);
    if (u == "WEEK") { int yo = p.year; return val_num(mysql_calc_week(p, mysql_week_mode(0), &yo)); }
